const p = $json.body || $json;
const company = p.company || 'there';
const niche = p.niche || 'local service';
const country = p.country || '';
const issue = p.issue || 'your online presence could convert more visitors into quote requests';
const websiteLine = p.website
  ? `I took a look at your online presence and noticed ${issue}.`
  : `I noticed ${company} has a real local presence, but I couldn't find a strong dedicated website that makes it easy to request a quote.`;

const variants = [
  {subject:`Quick idea for ${company}`, opener:`I came across ${company} while looking at ${niche} businesses in ${country}.`},
  {subject:`Website idea for ${company}`, opener:`I found ${company} while researching local ${niche} companies in ${country}.`},
  {subject:`A small idea for ${company}`, opener:`I was checking ${niche} businesses in ${country} and came across ${company}.`}
];
const v = variants[Math.floor(Math.random()*variants.length)];
const message = `Hi ${company} team,\n\n${v.opener}\n\n${websiteLine}\n\nI design clean websites for local service businesses, and I can also help with branding or flyers when needed.\n\nI can prepare a free homepage concept first so you can judge the direction before deciding anything.\n\nWould you like me to send the concept?\n\nBest,\n7KeySolutions`;

return [{json:{...p, subject:v.subject, message, approval_status:'pending', created_at:new Date().toISOString()}}];
